interface Krok {
    boolean wykonaj();
    void kompensuj();
}

class SagaOrchestrator {
    private final Deque<Krok> wykonaneKroki = new ArrayDeque<>();

    void uruchom(List<Krok> kroki) {
        for (Krok krok : kroki) {
            if (!krok.wykonaj()) {
                kompensujWszystko();
                return;
            }
            wykonaneKroki.push(krok);
        }
    }

    private void kompensujWszystko() {
        while (!wykonaneKroki.isEmpty()) {
            wykonaneKroki.pop().kompensuj(); // LIFO - odwrotna kolejnosc niz wykonanie
        }
    }
}

